function customStringify(obj) {
  const parts = [];
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    const value = typeof obj[key] === "string" ? `"${obj[key]}"` : obj[key];
    parts.push(`"${key}":${value}`);
  }
  return `{${parts.join(",")}}`;
}
